# Exact author calculations for new/replacement quantitative reasoning.
import sympy as sp
E=sp.Integer(64)*10**9;L=sp.Rational(1,5);outer=sp.Rational(1,50);inner=sp.Rational(1,100);force=sp.Integer(3)
diff=outer**4-inner**4;kr=3*sp.pi*E*diff/(64*L**3);ks=E*diff/(4*L**3);dr=force/kr*1000;ds=force/ks*1000
assert diff==sp.Rational(3,20000000)
assert kr==56250*sp.pi and ks==300000
assert dr==4/(75*sp.pi) and ds==sp.Rational(1,100)
assert round(float(dr),5)==.01698 and round(float(ds),5)==.01000
assert round(float(3*dr),5)==.05093 and round(float(3*ds),5)==.03000
assert round(float(dr/1000),8)==.00001698 and round(float(ds/1000),8)==.00001000
lag=F(50,100)/10-F(4,100);assert lag==F(1,100) and F(2)/lag==200
assert F(2)/(F(50,100)-F(4,100))==F(100,23) and F(2)/(F(50,100)/10)==40 and F(2,10)/lag==20
# Static support explanation: force and moment balance with signed reactions.
contact=sp.Matrix([[1,1,1],[0,2,0],[0,0,2]])
inside=contact.inv()*sp.Matrix([10,5,5]);outside=contact.inv()*sp.Matrix([10,15,15])
assert inside==sp.Matrix([5,sp.Rational(5,2),sp.Rational(5,2)])
assert outside==sp.Matrix([-5,sp.Rational(15,2),sp.Rational(15,2)])
assert 4-3==1
eta,ki,A,mod,length=sp.symbols('eta ki A E length',positive=True)
